// 目的：证明本次只改了注释，运行逻辑一个字节都没动。
const fs = require('fs');

function stripComments(src) {
  let out = '';
  let i = 0;
  const n = src.length;
  let state = 'code';       // code | line | block | sq | dq | tpl | regex
  let prevSignificant = '';  // 上一个有效字符，用于区分除号与正则
  while (i < n) {
    const c = src[i];
    const c2 = src[i + 1];
    if (state === 'code') {
      if (c === '/' && c2 === '/') { state = 'line'; i += 2; continue; }
      if (c === '/' && c2 === '*') { state = 'block'; i += 2; continue; }
      if (c === "'") { state = 'sq'; }
      else if (c === '"') { state = 'dq'; }
      else if (c === '`') { state = 'tpl'; }
      else if (c === '/' && /[=(,:[!&|?{};+\-*%^~<>]|^$/.test(prevSignificant)) { state = 'regex'; }
      out += c;
      if (!/\s/.test(c)) prevSignificant = c;
      i++;
      continue;
    }
    if (state === 'line') {
      if (c === '\n') { state = 'code'; out += c; }
      i++;
      continue;
    }
    if (state === 'block') {
      if (c === '*' && c2 === '/') { state = 'code'; i += 2; continue; }
      if (c === '\n') out += c;          // 保留行号结构
      i++;
      continue;
    }
    if (state === 'sq' || state === 'dq' || state === 'tpl') {
      out += c;
      if (c === '\\') { out += src[i + 1] || ''; i += 2; continue; }
      if ((state === 'sq' && c === "'") || (state === 'dq' && c === '"') || (state === 'tpl' && c === '`')) state = 'code';
      i++;
      continue;
    }
    if (state === 'regex') {
      out += c;
      if (c === '\\') { out += src[i + 1] || ''; i += 2; continue; }
      if (c === '/') state = 'code';
      i++;
      continue;
    }
  }
  // 去掉行尾空白，避免注释位置留下的空格差异造成假阳性
  return out.split('\n').map(l => l.replace(/\s+$/, '')).join('\n');
}

const a = fs.readFileSync(process.argv[2], 'utf8');
const b = fs.readFileSync(process.argv[3], 'utf8');
const sa = stripComments(a);
const sb = stripComments(b);
if (sa === sb) {
  console.log('OK: 去掉注释后两份文件完全一致 → 运行代码零改动');
  process.exit(0);
}
const la = sa.split('\n'), lb = sb.split('\n');
console.log('DIFF: 去掉注释后仍有差异，行数 ' + la.length + ' / ' + lb.length);
let shown = 0;
for (let i = 0; i < Math.max(la.length, lb.length) && shown < 30; i++) {
  if (la[i] !== lb[i]) {
    console.log('L' + (i + 1) + '\n  A: ' + JSON.stringify(la[i]) + '\n  B: ' + JSON.stringify(lb[i]));
    shown++;
  }
}
process.exit(1);
"}

